mapper.select:
SELECT mp.branchid, mp.memberid, mp.dayofweek, mp.method, mp.hour, mp.sortorder FROM ttokssaemdb.masterplan mp
AND mp.memberid = #{memberid}
ORDER BY mp.sortorder

SELECT rp.branchid, rp.memberid, rp.dayofweek, rp.method, rp.hour, rp.sortorder, rp.status FROM ttokssaemdb.runtimeplan rp
AND rp.memberid = #{memberid}
ORDER BY rp.sortorder

mapper.delete:
DELETE FROM 
  ttokssaemdb.runtimeplan
WHERE
  memberid = #{memberid}
  AND dayofweek = ${dayofweek}
